int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    cin >> n;

    auto sufficient = [n](long long sum) {
        __int128 a = sum / 2;
        __int128 b = sum - a;
        return a * b >= n;
    };

    long long low = 0, high = 1;
    while (!sufficient(high)) high *= 2;

    while (low < high) {
        long long mid = low + (high - low) / 2;
        if (sufficient(mid))
            high = mid;
        else
            low = mid + 1;
    }

    cout << low;
    return 0;
}

